head.script:
// 화면 리사이징

scwin.gBondYn = js_bond_yn;
scwin.vDepCd;
scwin.gIsurCd;
scwin.vIMKT_ID;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM); // 법인코드 및 법인명(회사명) 관련
        Grd_com_isur.style.zIndex = 30;
        scwin.hideDebugCtrls();
        // fn_SetCode();

        $c.cm.PanelToGroupBox(panel_1);
        $c.cm.PanelToGroupBox(panel_2);
        scwin.init();
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26701.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    // alert(frame.srcUrl);
    // return;
    // var parentWin = frame.Provider("../");
    // var paramObj = parentWin.gParamObj;
    // if (paramObj == undefined) return;

    let vIBAS_YY = $c.stf.getQuery(frame.srcUrl, "BAS_YY");
    let vIBAS_ACNTCLS_MM = $c.stf.getQuery(frame.srcUrl, "BAS_ACNTCLS_MM");
    let vIWRTRPT_KIND_CD = $c.stf.getQuery(frame.srcUrl, "WRTRPT_KIND_CD");
    scwin.vDepCd = $c.stf.getQuery(frame.srcUrl, "DEP_CD");
    txb_BAS_ACNTCLS_MM.setValue($c.stf.getQuery(frame.srcUrl, "BAS_ACNTCLS_MM"));
    txb_WRTRPT_KIND_CD.setValue($c.stf.getQuery(frame.srcUrl, "WRTRPT_KIND_CD"));
    txb_BAS_YY.setValue($c.stf.getQuery(frame.srcUrl, "BAS_YY"));
    txb_BAS_ACNTCLS_MM_YY.setValue($c.stf.getQuery(frame.srcUrl, "BAS_ACNTCLS_MM_YY"));
    txb_WRTRPT_KIND_CDNM.setValue($c.stf.getQuery(frame.srcUrl, "WRTRPT_KIND_CDNM"));
    txb_DEPT.setValue($c.stf.getQuery(frame.srcUrl, "DEP_CDNM"));
    edt_SCHDL_DD.setValue($c.stf.getQuery(frame.srcUrl, "WRTRPT_SUBMIT_SCHDL_DD"));
    scwin.vIMKT_ID = $c.stf.getQuery(frame.srcUrl, "MKT_ID");
    if (scwin.vIMKT_ID === '1') {
        txb_MKT_NM.setValue('유가');
        txb_MKT_CD.setValue('1');
    } else if (scwin.vIMKT_ID === '2') {
        txb_MKT_NM.setValue('코스닥');
        txb_MKT_CD.setValue('2');
    } else if (scwin.vIMKT_ID === '4') {
        scwin.gBondYn = 'Y';
    }

    // 분기보고서일때만 '자산총계' 항목 표출
    if (vIWRTRPT_KIND_CD === "3" || vIWRTRPT_KIND_CD === "6" || vIWRTRPT_KIND_CD === "B" || vIWRTRPT_KIND_CD === "D") {
        $c.cm.setColumnProp(grd_Grid, 'ASSETS', 'show', "true");
    } else {
        $c.cm.setColumnProp(grd_Grid, 'ASSETS', 'show', "false");
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_Grid_onheadcheckclick
 * @description grd_Grid onheadcheckclick 이벤트
 * @param {*} col col
 * @param {*} colid colid
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_onheadcheckclick = function(col, colid, bCheck) {
    try {
        // alert('grd_Grid.OnHeadCheckClick('+col+','+ colid+','+ bCheck+')');
        $c.lcd.fn_setCheckBox(colid, bCheck);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26701.grd_Grid_onheadcheckclick" });
    }
};

/**
 * @method
 * @name grd_Grid_OnClick
 * @description grd_Grid 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_OnClick = function(row, colid) {
    // fn_read(grd_Grid, row, colid);

};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        await scwin.read(grd_Grid, row, colid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26701.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26701.dts_Grid_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadError
 * @description dts_Grid 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26701.dts_Grid_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26701.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDSTF26701.xml', SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "제출현황목록", type: "2"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26701.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Modify_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Modify_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26701.btn_Modify_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert("성공적으로 처리 되었습니다.");
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26701.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert('trs_Save.OnFail() :' + trs_Save.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26701.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name btn_ISUR_CD_onclick
 * @description btn_ISUR_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ISUR_CD_onclick = function() {
    try {
        if (scwin.gBondYn === 'Y') {
            $c.cm.IsurcdSearchBond(txb_ISUR_CD, txb_COM_NM);
        } else {
            $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26701.btn_ISUR_CD_onclick" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onkeyup
 * @description txb_ISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onkeyup = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26701.txb_ISUR_CD_onkeyup" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onfocus
 * @description txb_ISUR_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
        Grd_com_isur.style.left = "92px";
        Grd_com_isur.style.top = "75px";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26701.txb_ISUR_CD_onfocus" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26701.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26701.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26701.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26701.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26701.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26701.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26701.MxDataSet_com_isur_OnFilter" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    $c.cm.setColumnProp(grd_Grid, 'CHECK_1', 'HeadCheck', "false");
    $c.cm.setColumnProp(grd_Grid, 'CHECK_2', 'HeadCheck', "false");
    $c.cm.setColumnProp(grd_Grid, 'CHECK_3', 'HeadCheck', "false");
    let vIBAS_YY = txb_BAS_YY.getValue();
    let vIBAS_ACNTCLS_MM = txb_BAS_ACNTCLS_MM.getValue();
    let vIWRTRPT_KIND_CD = txb_WRTRPT_KIND_CD.getValue();
    const vIISUR_CD = txb_ISUR_CD.getValue();
    const vIACP_YN = cmb_ACP_YN.getValue();
    const vILIST_STAT_CD = cmb_LIST_STAT_CD.getValue();
    const vATTATCH_YN = cmb_ATC_YN.getValue(); // 첨부확인 검색조건 추가 by LDJ_20130726

    url += "&BAS_YY=" + vIBAS_YY;
    url += "&BAS_ACNTCLS_MM=" + vIBAS_ACNTCLS_MM;
    url += "&WRTRPT_KIND_CD=" + vIWRTRPT_KIND_CD;
    url += "&ISUR_CD=" + vIISUR_CD;
    url += "&ACP_YN=" + vIACP_YN;
    url += "&MKT_ID=" + scwin.vIMKT_ID;
    url += "&DEP_CD=" + scwin.vDepCd;
    url += "&BOND_YN=" + scwin.gBondYn;
    url += "&LIST_STAT_CD=" + vILIST_STAT_CD;
    url += "&WRTRPT_SUBMIT_OBJ_ISU_YN=" + cmb_WRTRPT_SUBMIT_OBJ_ISU_YN.getValue();
    url += "&WRTRPT_ANL_OBJ_ISU_YN=" + cmb_WRTRPT_ANL_OBJ_ISU_YN.getValue();
    url += "&WRTRPT_STAT_OBJ_ISU_YN=" + cmb_WRTRPT_STAT_OBJ_ISU_YN.getValue();
    url += "&ATTATCH_YN=" + cmb_ATC_YN.getValue(); // 첨부확인 검색조건 추가 by LDJ_20130726
    url += "&SCREN_ID=" + 'ULDSTF26701.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/SubmitStatus.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function() {
    trs_Save.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/SubmitStatus.do",
        ref : "dts_Grid",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name read
 * @description read 처리
 * @param {String} GridID GridID
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.read = async function(GridID, row, colid) {
    if (row < 1) return;
    const objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..
    if (colid === "WRTRPT_KIND_CDNM") {
        let AcptNo = objDataID.getCellData(row, "ACPT_NO");
        if (AcptNo !== "") {
            await $c.stf.openDisclViewer(AcptNo, "R");
        }
    } else if (colid === "COM_ABBRV") {
        scwin.setContnId(row);
        $c.stf.fn_PopupCorpInfo();
    } else if (colid === "SUBMIT_YN") {
        let AcptNo = objDataID.getCellData(row, "ACPT_NO");
        if (AcptNo === "") {
            if (scwin.vIMKT_ID === '2') {
                // 코스닥일때만 적용
                // 미제출일때만 링크한다.
                await scwin.openNSubmitMgt(objDataID.getCellData(row, "ISUR_CD"));
            }
        } else {
            // 제출일땐 공시뷰어 링크
            await $c.stf.openDisclViewer(AcptNo, "R");
        }
    } else if (colid === "DELIST_DD") {
        const DelAcptNo = objDataID.getCellData(row, "DELIST_ACPT_NO");
        if (DelAcptNo !== "") {
            await $c.stf.openDisclViewer(DelAcptNo, "R");
        }
    }
};

/**
 * @method
 * @name openNSubmitMgt
 * @description open NSubmit Mgt 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openNSubmitMgt = async function(obj) {
    let url = "/dsclsrch/ULDSTF26610.gfm?ISUR_CD=" + obj;
    const winTitle = "정기보고서 미제출법인 관리";
    await $c.frame.CreateDialogFrame("NSUBMITINFO1", url, winTitle, 10, 10, 700, 350, "window");
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (dts_Grid.getRowCount() === 0) {
        await $c.win.alert("대상을 선택하세요");
        return;
    }
    let gCnt = 0;
    let gStat;
    grd_Grid.Redraw = false;
    dts_Grid.setBroadcast(false);
    for (let k = 1; k <= dts_Grid.getRowCount(); k++) {
        gStat = dts_Grid.getRowStatus(k);
        if (gStat === TB_JOB_UPDATE) {
            gCnt++;
            const str_1 = (dts_Grid.getCellData(k, "CHECK_1") === 'T' ? 'Y' : 'N');
            const str_2 = (dts_Grid.getCellData(k, "CHECK_2") === 'T' ? 'Y' : 'N');
            const str_3 = (dts_Grid.getCellData(k, "CHECK_3") === 'T' ? 'Y' : 'N');
            dts_Grid.setCellData(k, "WRTRPT_SUBMIT_OBJ_ISU_YN", str_1);
            dts_Grid.setCellData(k, "WRTRPT_ANL_OBJ_ISU_YN", str_2);
            dts_Grid.setCellData(k, "WRTRPT_STAT_OBJ_ISU_YN", str_3);
        }
    }
    dts_Grid.setBroadcast(true, true);
    grd_Grid.Redraw = true;

    // alert(dts_Grid.text);

    if (gCnt === 0) {
        await $c.win.alert("저장할 내용이 없습니다.");
        return;
    }
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", '총 ' + gCnt + '건을 저장'))) return;
    await scwin.trs();
};

/**
 * @method
 * @name hideDebugCtrls
