/**
 * @method
 * @name setCheckBox
 * @description set Check Box 처리
 * @param {*} colid colid
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.setCheckBox = function(colid, bCheck) {
    let vcd = "";
    if (bCheck === '1') {
        vcd = "T";
    } else {
        vcd = "F";
    }
    grd_Grid.Redraw = false;
    dts_Grid.setBroadcast(false);
    for (let i = 1; i <= dts_Grid.getRowCount(); i++) {
        dts_Grid.setCellData(i, colid, vcd);
    }
    dts_Grid.setBroadcast(true, true);
    grd_Grid.Redraw = true;
};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gIsurCd = dts_Grid.getCellData(Number(obj), "ISUR_CD");
    // alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);

};

